import{experimentResult,storeCases}from './phy1-models.js?v=20261023-physicscomplete01';let seq=0;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const T=(x,y,s,n=17,c='#faf5ed')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${E(s)}</text>`;const L=(x,y,u,v,c='#bccfcb',w=3)=>`<path d="M${x} ${y}L${u} ${v}" fill="none" stroke="${c}" stroke-width="${w}"/>`;const B=(x,y,w,h,c='#365463')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="${c}" stroke="#a8c4be"/>`;const dot=(x,y,r=7,c='#efb499')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;const fmt=n=>Number(Number(n).toFixed(3));
export function phy1SVG(body,label){return`<svg viewBox="0 0 560 440" role="img" aria-label="${E(label)}">${body}</svg>`;}
const orb=(x,y,r)=>{let id='phy1-orb-'+(++seq);return`<defs><radialGradient id="${id}" cx="30%" cy="25%"><stop stop-color="#ffefd7"/><stop offset=".35" stop-color="#e9b38a"/><stop offset="1" stop-color="#8d634d"/></radialGradient></defs><ellipse cx="${x+4}" cy="${y+r+13}" rx="${r*.9}" ry="7" fill="#0e2534" opacity=".4"/><circle cx="${x}" cy="${y}" r="${r}" fill="url(#${id})"/>`;};
const bar=(x,y,label,value,max=400,c='#dcb89b')=>T(x+115,y-10,label+': '+fmt(value)+' J',15)+`<rect x="${x}" y="${y}" width="230" height="18" rx="5" fill="#ffffff12"/><rect x="${x}" y="${y}" width="${230*value/max}" height="18" rx="5" fill="${c}"/>`;
export function launchFigure(p=0){let fraction=4*p*(1-p),h=20*fraction,ke=400*(1-fraction),pe=400*fraction,y=325-h*11,a=T(280,28,'Ideal upward launch: same 400 J throughout',22)+L(55,355,270,355)+orb(160,y,25)+T(160,395,fmt(h)+' m above launch level',15)+bar(300,115,'Kinetic',ke)+bar(300,200,'Gravitational',pe,400,'#afc7bc')+T(415,285,'Total 400 J',21)+T(280,427,'2 kg · g = 10 N/kg · no air resistance · replay resets the example',12);return phy1SVG(a,`Ideal2kg launch with g = 10N/kg; height${fmt(h)}m, kinetic${fmt(ke)}J, gravitational${fmt(pe)}J, closed total 400J. No air resistance; replay resets an example rather than creating energy.`);}
export function storeFigure({a='launch',revealed=true}={}){let r=storeCases[a],body=T(280,30,'Use the same joule scale for every store',22)+T(280,73,r.label+' · target: '+r.target,17);for(let[i,v]of r.values.entries())body+=bar(165,130+i*85,r.names[i],v);body+=T(280,388,revealed?'Accounted total 400 J · target '+r.value+' J':'Predict the named target store',20)+T(280,430,'Original wider-system snapshots · pathways are not extra stores',13);return phy1SVG(body,r.label+' original final store account: '+r.names.map((n,i)=>n+' '+r.values[i]+'J').join('; ')+'. Total 400J. '+(revealed?'Target'+r.target+' '+r.value+'J.':'Predict target.'));}
export function kineticFigure({a='2',b='3',revealed=true,progress=.4,movie=false}={}){let r=experimentResult('kinetic',a,b),x=movie?80+400*progress:110+r.v*45,body=T(280,28,'Kinetic energy grows with speed squared',22)+L(45,277,520,277,'#9cb6b5',3)+`<ellipse cx="${x}" cy="274" rx="65" ry="11" fill="#102837" opacity=".5"/><path d="M${x-52} 217l18 -16h90l-15 16z" fill="#c7d8d6"/><rect x="${x-52}" y="217" width="93" height="44" rx="10" fill="#83a8ab"/><path d="M${x+41} 217l15 -16v43l-15 17z" fill="#456f7c"/>`+dot(x-30,265,12,'#e0c4a5')+dot(x+24,265,12,'#e0c4a5')+T(x,244,r.m+' kg',17,'#102c3c')+T(280,100,'Ek = ½ ×'+r.m+' ×'+r.v+'²',22)+L(x-15,160,x+45,160,'#edb69b',4)+T(x+20,145,r.v+' m/s',17)+T(280,330,revealed?'Kinetic energy: '+r.value+' J':'Predict kinetic energy',24)+bar(165,375,'Energy scale',r.value,80)+T(280,431,'No friction, rotation or collision model · visual travel speed symbolic',12);return phy1SVG(body,`Cart mass${r.m}kg, speed${r.v}m/s; `+(revealed?`kinetic energy${r.value}J`:'predict kinetic energy')+'. Original comparison; display travel timing symbolic, not a stopping-distance model.');}
export function liftFigure({a='2',b='3',revealed=true,progress=1}={}){let r=experimentResult('gravitational',a,b),h=r.h*progress,y=330-h*30,body=T(280,28,'Change the vertical height, not the route length',21)+L(70,355,500,355)+L(110,350,110,105)+T(95,95,'m',15)+B(240,y-45,90,70,'#9cbfc0')+`<path d="M240 ${y-45}l17 -14h90l-17 14z" fill="#c9dbd4"/><path d="M330 ${y-45}l17 -14v70l-17 14z" fill="#5f8693"/>`+T(285,y-3,r.m+' kg',20,'#143243')+T(415,145,'g =10 N/kg',18)+T(415,190,fmt(h)+' m rise',21)+T(280,395,revealed?'ΔEp = '+fmt(r.m*10*h)+' J':'Predict gravitational energy gain',22)+T(280,431,'Object–Earth system · chosen reference · idealised work/energy route',12);for(let i=0;i<7;i++)body+=L(103,350-i*30,118,350-i*30)+T(86,355-i*30,i,13);return phy1SVG(body,`Object–Earth model: mass${r.m}kg, g = 10N/kg, vertical rise${fmt(h)}m. `+(revealed?'Energy gained'+fmt(r.m*10*h)+'J.':'Predict gain.')+' Reference at the lower line; no calibrated lift time.');}
export function springFigure({a='100',b='0.1',revealed=true,progress=1}={}){let r=experimentResult('elastic',a,b),e=r.e*progress,end=230+e*750,body=T(280,28,'Measure extension from the natural position',22)+L(70,120,70,295,'#b8cac7',8)+L(70,210,105,210),d='M105 210';for(let i=1;i<=32;i++)d+='L'+(105+(end-105)*i/32)+' '+(210+Math.sin(i*Math.PI/2)*16);body+=`<path d="${d}" fill="none" stroke="#d2bba2" stroke-width="6" stroke-linejoin="round"/>`+orb(end+22,210,22)+L(230,280,230,315)+L(end,280,end,315)+L(230,302,end,302,'#e9b49a',2)+T((230+end)/2,340,'extension '+fmt(e)+' m',17)+T(280,90,'k = '+r.k+' N/m · Ee = ½ke²',22)+T(280,385,revealed?'Stored energy: '+fmt(.5*r.k*e*e)+' J':'Predict elastic energy',23)+T(280,428,'Supported extension ≤0.20 m · proportional range assumed, not a safety limit',12);return phy1SVG(body,`Spring model k${r.k}N/m, extension${fmt(e)}m from natural position. `+(revealed?'Elastic energy'+fmt(.5*r.k*e*e)+'J.':'Predict energy.')+' Only stated proportional range supported; not a universal safe extension.');}
export function heatingFigure({a='0.5',b='0',revealed=true,progress=1}={}){let r=experimentResult('heating',a,b),theta=20+r.delta*progress,body=T(280,28,'Separate heater input from block energy gain',22)+B(95,145,245,130,'#87a8ad')+`<path d="M95 145l28 -24h245l-28 24z" fill="#bdcfcd"/><path d="M340 145l28 -24v130l-28 24z" fill="#4e7484"/>`+T(218,205,r.m+' kg block',23,'#173545')+T(218,239,'c = 1000 J/(kg°C)',16,'#173545')+`<path d="M150 145V92H285V145" stroke="#e5b38f" stroke-width="7" fill="none"/><rect x="410" y="120" width="18" height="170" rx="9" fill="#b4c9ce"/><rect x="414" y="${285-(theta-20)*10}" width="10" height="${Math.max(3,(theta-20)*10)}" rx="5" fill="#eea58d"/>`+T(425,330,revealed?fmt(theta)+'°C':'Predict rise',21)+T(218,330,'Input '+fmt(6000*progress)+' J',19)+T(280,372,'Block '+fmt(r.block*progress)+' J · elsewhere '+fmt(r.elsewhere*progress)+' J',18)+T(280,409,revealed?'Δθ '+fmt(r.delta*progress)+'°C · apparent c '+fmt(r.apparent):'Use ΔE = mcΔθ with the correct boundary',16)+T(280,433,'Original virtual readings · uniform block, constant c, no phase change',12);return phy1SVG(body,`Original block${r.m}kg starts20°C, heater input${fmt(6000*progress)}J; block gain${fmt(r.block*progress)}J, surroundings${fmt(r.elsewhere*progress)}J. `+(revealed?`Temperature${fmt(theta)}°C, rise${fmt(r.delta*progress)}°C; apparent c using input${fmt(r.apparent)}J/(kg°C).`:'Predict rise.')+' Model actual c = 1000; not physical practical competence.');}
const evidence={stores:['Stores: kinetic, thermal, chemical, elastic, gravitational','Also magnetic, electrostatic and nuclear stores','Transfer: mechanical, electrical, heating, radiation'],kinetic:['Ek = ½mv² · kg, m/s and J','Double speed → four times energy','Double mass → twice energy'],gravitational:['ΔEp = mgΔh · use the supplied g','Height change is vertical from a chosen reference','Object–Earth system; other transfers may matter'],elastic:['Ee = ½ke² · N/m, m and J','Extension = stretched length − original length','Apply only within the stated proportional range'],heating:['ΔE = mcΔθ · Δθ = final − initial','c = energy / (mass × temperature rise)','RP1 Physics / RP14 Trilogy · physical evidence outstanding']};
export function physicsFigure(o={}){if(o.concealed)return phy1SVG(T(280,220,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');let k=o.kind||'stores',base=k.replace(/-(model|data)$/,'');if(k.endsWith('-model'))return({stores:storeFigure,kinetic:kineticFigure,gravitational:liftFigure,elastic:springFigure,heating:heatingFigure}[base])(o);let rows=evidence[base];return phy1SVG(T(280,35,'Connect the quantities, units and mechanism',21)+rows.map((s,i)=>T(280,130+i*90,s,16)).join('')+T(280,430,'Original teaching representation · state the system and assumptions',12),rows.join('. '));}
